import os,sys,json,time,pathlib,subprocess,hashlib,urllib.request,zipfile,base64,traceback
from datetime import datetime,timezone
TEX_B64=''
MAP_B64=''
TEX_HASH='9e778a15bc13bf6339b374de44febbf54763715854f94aac3a252fb6b0cc1f0b'
MAP_HASH='cfd3860cb2176ce62c18f656987b96a12fed9185db6f95767b409b87acc6be8e'
ROOT=pathlib.Path('/content/tep-concentrated-appendix106')
ROOT.mkdir(exist_ok=False)
OUT=ROOT/'evidence';OUT.mkdir()
PUB=ROOT/'public-package';PUB.mkdir()
report={'schema':1,'started_utc':datetime.now(timezone.utc).isoformat(),'steps':[],
        'status':'PENDING','new_lean_run':False,'independent_review':False,
        'artifact_marker':'Official bundled marker executed once on host immediately before TeX authoring; no duplicate marker here'}
def digest(p):return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
def run(name,args):
 t=time.monotonic()
 p=subprocess.run(args,cwd=OUT,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,
     env=dict(os.environ,DEBIAN_FRONTEND='noninteractive',SOURCE_DATE_EPOCH='1793577600',FORCE_SOURCE_DATE='1',TZ='UTC'))
 (OUT/(name+'.log')).write_text(p.stdout)
 row={'name':name,'exit_code':p.returncode,'seconds':round(time.monotonic()-t,3)}
 report['steps'].append(row);print(json.dumps(row),flush=True)
 if p.returncode:raise RuntimeError(name+' failed: '+p.stdout[-2500:])
 return p.stdout
try:
 tex=base64.b64decode(TEX_B64);mapping=base64.b64decode(MAP_B64)
 if hashlib.sha256(tex).hexdigest()!=TEX_HASH:raise ValueError('TeX hash mismatch')
 if hashlib.sha256(mapping).hexdigest()!=MAP_HASH:raise ValueError('Map hash mismatch')
 (OUT/'concentrated-chain-appendix.tex').write_bytes(tex)
 (OUT/'declaration-map.json').write_bytes(mapping)
 m=json.loads(mapping)
 if len(m['declarations'])!=18 or len({x['declaration'] for x in m['declarations']})!=18:raise ValueError('Eighteen unique declarations required')
 if m['public_code_revision']!='9699c2a0d50e7d722ac20c6f9ea263ee4eaeac6a':raise ValueError('Code pin mismatch')
 if m['proof_source']!='9e6298ef199961ff14e94db3dfd2e297ec931fc6':raise ValueError('Proof pin mismatch')
 if m['private_access_state_included'] or m['new_lean_execution'] or m['independent_review']:raise ValueError('Wrong scope')
 fetched=[]
 for path,want in m['allowlist'].items():
  rel=pathlib.PurePosixPath(path)
  if rel.is_absolute() or '..' in rel.parts or not path.startswith(('YangMills/RG/','reproducibility/actual-concentrated-')):raise ValueError('Unsafe allowlist path')
  if rel.suffix not in {'.lean','.json','.md','.py','.ps1'}:raise ValueError('Wrong public file type')
  data=urllib.request.urlopen('https://raw.githubusercontent.com/lluiseriksson/THE-ERIKSSON-PROGRAMME/'+m['public_code_revision']+'/'+path).read().replace(b'\r\n',b'\n')
  if hashlib.sha256(data).hexdigest()!=want:raise ValueError('Public source mismatch: '+path)
  target=PUB/path;target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(data)
  fetched.append({'path':path,'sha256_lf':want})
 if len(fetched)!=70:raise ValueError('Expected seventy allowlisted files')
 for stage in ['actual-concentrated-repair-20261101/100','actual-concentrated-repair-mean-20261102/101','actual-concentrated-coexact-rank-20261102/102','actual-concentrated-volume-rank-20261102/103','actual-concentrated-family-obstruction-20261102/105']:
  a=json.loads((PUB/('reproducibility/'+stage+'-validation.json')).read_text())
  b=json.loads((PUB/('reproducibility/'+stage+'b-validation.json')).read_text())
  for key in ['source_sha','target_olean_sha256','oracle_log_sha256','source_manifest_sha256']:
   if a[key]!=b[key]:raise ValueError('Historical pair mismatch: '+stage+' '+key)
  if a['exit_zero_steps']!=9 or b['exit_zero_steps']!=9:raise ValueError('Historical compiler steps mismatch')
 (OUT/'allowlist-fetch.json').write_text(json.dumps(fetched,indent=2))
 report['allowlist_count']=len(fetched);report['declaration_count']=18
 run('apt-update',['apt-get','update','-qq'])
 run('apt-install',['apt-get','install','-y','-qq','texlive-latex-recommended','texlive-fonts-recommended','lmodern','poppler-utils'])
 run('pip-render',['python','-m','pip','install','-q','PyMuPDF==1.26.7'])
 run('pdflatex-pass1',['pdflatex','-interaction=nonstopmode','-halt-on-error','concentrated-chain-appendix.tex'])
 run('pdflatex-pass2',['pdflatex','-interaction=nonstopmode','-halt-on-error','concentrated-chain-appendix.tex'])
 run('pdfinfo',['pdfinfo','concentrated-chain-appendix.pdf'])
 run('pdftotext',['pdftotext','-layout','concentrated-chain-appendix.pdf','appendix.txt'])
 run('pdftoppm',['pdftoppm','-r','110','-png','concentrated-chain-appendix.pdf','page'])
 import fitz
 pdf=fitz.open(OUT/'concentrated-chain-appendix.pdf')
 pages=len(pdf)
 if pages<3 or pages>12:raise ValueError('Unexpected appendix page count')
 if len(list(OUT.glob('page-*.png')))!=pages:raise ValueError('Render page count mismatch')
 anchors=['Original local nonlinear data','Uniform bounded-rank consequence','Model assessments and review context','Formal coverage and reproduction record']
 text=' '.join((OUT/'appendix.txt').read_text().split())
 if not all(x in text for x in anchors):raise ValueError('Text anchor missing (presence check only)')
 log=(OUT/'concentrated-chain-appendix.log').read_text(errors='replace')
 warnings=[x for x in log.splitlines() if 'Overfull' in x or 'Underfull' in x or 'LaTeX Warning' in x]
 if any('Overfull' in x or 'undefined' in x.lower() for x in warnings):raise ValueError('Unresolved layout/reference warnings: '+repr(warnings))
 report.update(pages=pages,pdf_sha256=digest(OUT/'concentrated-chain-appendix.pdf'),tex_sha256=TEX_HASH,map_sha256=MAP_HASH,layout_warnings=warnings)
 for name in ['concentrated-chain-appendix.pdf','concentrated-chain-appendix.tex','declaration-map.json']:
  (PUB/name).write_bytes((OUT/name).read_bytes())
 driver_bytes=pathlib.Path(__file__).read_bytes()
 (PUB/'render106.py').write_bytes(driver_bytes)
 report['driver_sha256']=hashlib.sha256(driver_bytes).hexdigest()
 (PUB/'REPRODUCE.txt').write_text('Existing-paper appendix, not a deposit. Code revision '+m['public_code_revision']+'; exact proof '+m['proof_source']+'.\nRun the preserved reproduction scripts only in your own authorized Colab Linux runtime. They fetch their original exact proof SHAs, check pins, compile and print exact axiom reports. This assembly performs no new Lean verification.\nNo access-state snapshots or credentials are included. Read all first-assessment reports and preserved failures. No independent review or editorial acceptance is claimed.\n')
 manifest={str(p.relative_to(PUB)):digest(p) for p in sorted(PUB.rglob('*')) if p.is_file()}
 (PUB/'sha256-manifest.json').write_text(json.dumps(manifest,indent=2))
 public_zip=OUT/'public-reproducibility.zip'
 with zipfile.ZipFile(public_zip,'w',zipfile.ZIP_DEFLATED) as z:
  for p in sorted(PUB.rglob('*')):
   if p.is_file():z.write(p,str(p.relative_to(PUB)))
 report['public_package_entries']=len(manifest)+1
 report['public_package_sha256']=digest(public_zip)
 report['status']='PDF_COMPILED_ALL_PAGES_RENDERED_AWAITING_FIRST_VISUAL_REVIEW'
 (OUT/'tool-versions.txt').write_text(subprocess.getoutput('pdflatex --version')+'\n'+subprocess.getoutput('pdftoppm -v')+'\nPyMuPDF '+fitz.VersionBind)
 (OUT/'package-versions.txt').write_text(subprocess.getoutput('dpkg-query -W texlive-latex-recommended texlive-fonts-recommended lmodern poppler-utils'))
except BaseException as e:
 report['status']='FAIL';report['error']=str(e)
 (OUT/'exception.txt').write_text(traceback.format_exc());print(traceback.format_exc(),flush=True)
finally:
 report['finished_utc']=datetime.now(timezone.utc).isoformat()
 (OUT/'report.json').write_text(json.dumps(report,indent=2))
 manifest={p.name:digest(p) for p in sorted(OUT.iterdir()) if p.is_file()}
 (OUT/'manifest.json').write_text(json.dumps(manifest,indent=2))
 bundle=ROOT/'render106.zip'
 with zipfile.ZipFile(bundle,'w',zipfile.ZIP_DEFLATED) as z:
  for p in sorted(OUT.iterdir()):
   if p.is_file():z.write(p,p.name)
 print('FINAL_REPORT='+json.dumps(report),flush=True)
 print('EVIDENCE_BASE64_BEGIN='+base64.b64encode(bundle.read_bytes()).decode()+'=EVIDENCE_BASE64_END',flush=True)
 print('INLINE_EVIDENCE_EMITTED; releasing runtime.',flush=True)
 from google.colab import runtime
 runtime.unassign()
